import { test, before, after } from 'node:test';
import assert from 'node:assert/strict';
import { createServer } from '../../server/server.js';
import { applyDiscount } from '../../server/discounts.js';

let server, base;
before(async () => {
  server = createServer().listen(0, '127.0.0.1');
  await new Promise((r) => server.once('listening', r));
  base = `http://127.0.0.1:${server.address().port}`;
});
after(() => server.close());

const apply = (code) =>
  fetch(`${base}/api/cart/discount`, {
    method: 'POST',
    headers: { 'content-type': 'application/json' },
    body: JSON.stringify({ code }),
  });

test('SHOP-142 AC-2 SAVE10 takes 10% off a $120 cart (total 108.00)', async () => {
  const res = await apply('SAVE10');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.discount, 12);
  assert.equal(body.total, 108);
});

test('SHOP-142 AC-2 FLAT20 takes $20 off a $120 cart (total 100.00)', async () => {
  const res = await apply('FLAT20');
  assert.equal(res.status, 200);
  const body = await res.json();
  assert.equal(body.discount, 20);
  assert.equal(body.total, 100);
});

test('SHOP-142 AC-2 codes are not case-sensitive (save10 is accepted)', async () => {
  const res = await apply('save10');
  assert.equal(res.status, 200, 'lower-case save10 should be accepted');
  assert.equal((await res.json()).total, 108);
});

test('SHOP-142 AC-3 an unknown code is refused with a message', async () => {
  const res = await apply('NOPE99');
  assert.equal(res.status, 400);
  assert.match((await res.json()).error, /\S/);
});

test('SHOP-142 AC-3 an expired code (WELCOME5) is refused with a message', async () => {
  const res = await apply('WELCOME5');
  assert.equal(res.status, 400, 'WELCOME5 expired on 2025-06-30 and must be refused');
  assert.match((await res.json()).error, /\S/);
});

test('SHOP-142 AC-3 FLAT20 under $50 is refused and the message names $50', () => {
  // The demo cart is fixed at $120, so the minimum-order rule is checked on the discount logic.
  const result = applyDiscount('FLAT20', 40);
  assert.equal(result.ok, false);
  assert.match(result.error, /\$50/);
});
